export function getEligibleQuestions(level: number, color?: string): BankQuestion[] {
  return LOCAL_QUESTION_BANK.filter((q) => {
    if (q.level !== level) return false;
    if (color && q.color !== color) return false;
    if (level <= 3) {
      return q.difficulty === 'EASY';
    } else {
      return q.difficulty === 'MEDIUM' || q.difficulty === 'HARD';
    }
  });
}
